def longest_substring_at_most_twice(s):
    counts={};left=0;answer=0
    for right,char in enumerate(s):
        counts[char]=counts.get(char,0)+1
        while counts[char]>2:
            counts[s[left]]-=1;left+=1
        answer=max(answer,right-left+1)
    return answer

